import {setIconSwitchState,nextSwitchState} from './icon-switch.js';
import {commitThemeChange} from './theme-change.js';
export function validateBackground(file){if(!file||!/^image\/(jpeg|png|webp|avif|gif)$/.test(file.type))return 'Choose a JPG, PNG, WebP, AVIF or GIF image.';if(file.size>25*1024*1024)return 'Choose an image smaller than 25 MB.';return '';}
const $=id=>document.getElementById(id);
async function database(){return new Promise((resolve,reject)=>{const r=indexedDB.open('prem-room',1);r.onupgradeneeded=()=>r.result.createObjectStore('environment');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
async function saveRoom(value){const db=await database();return new Promise((resolve,reject)=>{const tx=db.transaction('environment','readwrite');if(value)tx.objectStore('environment').put(value,'background');else tx.objectStore('environment').delete('background');tx.oncomplete=()=>{db.close();resolve();};tx.onerror=()=>{db.close();reject(tx.error);};});}
async function readRoom(){const db=await database();return new Promise((resolve,reject)=>{const tx=db.transaction('environment');const r=tx.objectStore('environment').get('background');r.onsuccess=()=>{db.close();resolve(r.result);};r.onerror=()=>{db.close();reject(r.error);};});}
export function initEnvironment({onThemeChange=()=>{}}={}){let objectURL=null,loading=false,version=0,theme='light';try{theme=localStorage.getItem('prem-theme')||theme;}catch{}
 const systemTheme=matchMedia('(prefers-color-scheme: dark)');
 function setTheme(value,announce=true){
  theme=['dark','light','system'].includes(value)?value:'light';
  const effective=theme==='system'?(systemTheme.matches?'dark':'light'):theme;
  commitThemeChange(document.documentElement,()=>{
   document.documentElement.dataset.theme=effective;document.documentElement.dataset.themePreference=theme;
   setIconSwitchState($('themeToggle'),theme);
   document.querySelectorAll('[data-theme-choice]').forEach(b=>{const active=b.dataset.themeChoice===theme;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});
  });try{localStorage.setItem('prem-theme',theme);}catch{}if(announce)onThemeChange(theme);
 }
 setTheme(theme,false);$('themeToggle').onclick=()=>setTheme(nextSwitchState(['light','dark','system'],theme));document.querySelectorAll('[data-theme-choice]').forEach(b=>b.onclick=()=>setTheme(b.dataset.themeChoice));
 systemTheme.addEventListener('change',()=>{if(theme==='system')setTheme('system',false);});
 for(const [key,fallback,unit] of [['glassOpacity',45,'%'],['roomBlur',12,'px'],['roomShade',18,'%']]){const input=$(key);let value=fallback;try{value=Number(localStorage.getItem('prem-'+key)||fallback);}catch{}input.value=value;const apply=()=>{const v=+input.value;$(key+'Value').value=v+unit;if(key==='roomBlur')document.documentElement.dataset.roomBlur=v>0?'on':'off';document.documentElement.style.setProperty(key==='glassOpacity'?'--glass-alpha':key==='roomBlur'?'--room-blur':'--room-shade',key==='roomBlur'?v+'px':String(v/100));try{localStorage.setItem('prem-'+key,String(v));}catch{}};input.oninput=apply;apply();}
 function showRoom(data){if(objectURL)URL.revokeObjectURL(objectURL);objectURL=URL.createObjectURL(data.blob);$('roomBackdrop').style.backgroundImage=`url("${objectURL}")`;document.body.classList.add('has-room');$('roomName').textContent=data.name||'Room background';$('removeRoom').hidden=false;$('roomStatus').textContent='Room background applied.';}
 async function loadRoom(file){const error=validateBackground(file);if(error){$('settings').hidden=false;$('roomStatus').textContent=error;return;}if(loading)return;loading=true;const request=++version;$('roomStatus').textContent='Preparing image…';try{const bitmap=await createImageBitmap(file);const ratio=Math.min(1,2560/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*ratio);canvas.height=Math.round(bitmap.height*ratio);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/webp',.86));if(!blob)throw Error('decode');if(request!==version)return;const data={blob,name:file.name};showRoom(data);try{await saveRoom(data);}catch{$('roomStatus').textContent='Background applied for this session.';}}catch{$('settings').hidden=false;$('roomStatus').textContent='Could not open that image. Try a JPG or PNG.';}finally{loading=false;$('roomFile').value='';}}
 $('chooseRoom').onclick=()=>$('roomFile').click();$('roomFile').onchange=e=>loadRoom(e.target.files[0]);$('removeRoom').onclick=async()=>{version++;if(objectURL)URL.revokeObjectURL(objectURL);objectURL=null;$('roomBackdrop').style.backgroundImage='';document.body.classList.remove('has-room');$('roomName').textContent='Drop a room image';$('removeRoom').hidden=true;$('roomStatus').textContent='';try{await saveRoom(null);}catch{}};
 let depth=0;const files=e=>[...(e.dataTransfer?.types||[])].includes('Files');window.addEventListener('dragenter',e=>{if(files(e)){e.preventDefault();depth++;$('roomDropOverlay').hidden=false;}});window.addEventListener('dragover',e=>{if(files(e)){e.preventDefault();e.dataTransfer.dropEffect='copy';}});window.addEventListener('dragleave',e=>{if(files(e)){depth=Math.max(0,depth-1);if(!depth)$('roomDropOverlay').hidden=true;}});window.addEventListener('drop',e=>{if(files(e)){e.preventDefault();depth=0;$('roomDropOverlay').hidden=true;loadRoom(e.dataTransfer.files[0]);}});window.addEventListener('blur',()=>{depth=0;$('roomDropOverlay').hidden=true;});
 const initialVersion=version;readRoom().then(data=>{if(data&&version===initialVersion&&!objectURL)showRoom(data);}).catch(()=>{});
}
